import{z as A,x as B,o as e,c as d,q as n,j as i,D as r,d as o,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Tor 洋葱路由","description":"","frontmatter":{"title":"Tor 洋葱路由","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tor-onion-routing.md","filePath":"cs/tor-onion-routing.md","lastUpdated":1791413859000}'),p={name:"cs/tor-onion-routing.md"};function T(h,a,m,u,D,c){const t=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="tor-洋葱路由" tabindex="-1">Tor 洋葱路由 <a class="header-anchor" href="#tor-洋葱路由" aria-label="Permalink to &quot;Tor 洋葱路由&quot;">​</a></h1><div class="epigraph"><p>洋葱路由把电路上的每一跳只看见相邻，出口看见明文目的（若无端到端加密）。匿名是概率与威胁模型：全局被动观察者仍强。</p><footer>—— Dingledine, Mathewson and Syverson, Tor, USENIX Security 2004</footer></div><p>上一课<a href="/cs/pir">PIR</a>藏的是数据库下标；本课的缺口是<strong>藏网络身份与路径</strong>——谁在连、连到哪。本课讲 Tor 的机制与极限，不写滥用教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TLS 保护内容，但对服务器仍暴露客户端 IP，对本地观察者连目的都可见。Tor 的回答是三跳电路加分层加密：客户端与每一跳分别协商密钥，报文像洋葱一样逐层加封，每一跳只能剥开自己那层、只看见相邻两跳。缺口是出口策略、时序关联与网桥的可达性。</p><h3 id="端到端仍要" tabindex="-1">端到端仍要 <a class="header-anchor" href="#端到端仍要" aria-label="Permalink to &quot;端到端仍要&quot;">​</a></h3><p>出口节点剥掉最后一层后转发：若应用层没有端到端加密，出口能看见甚至篡改内容。匿名与保密是两件事——Tor 藏「谁在连」，TLS 藏「说了什么」，缺一不可。</p><p><span class="marginnote">常见误区：以为挂了 Tor 内容就自动加密了。实际上洋葱加密只护到出口为止，出口之后就是明文；网页侧的 HTTPS 是你自己（或网站）开启的另一层，两者管的不是同一段路。</span></p><p><span class="marginnote">Dingledine et al. 2004。禁止攻击 Tor 用户的指导。安全经济学下一课换激励。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把洋葱封装画清楚，再对照 VPN：VPN 是单跳信任，运营者同时看见两端，天然可关联进出流量；Tor 把「同时看见两端」的能力拆给三个互不串通的节点，单看任何一跳都拼不出完整映射。电路按分钟级周期更换，而守卫节点固定一段较长时间，以免频繁换入口反而扩大可关联面。下一课安全经济学。</p><p><span class="marginnote">术语翻译：守卫节点就是你固定使用的第一个中转站。可以想象成总去同一家快递网点寄件——网点认得你，但不知道收件人是谁；换得太勤，反而让更多网点有机会同时看到「你寄件」这件事。</span></p>',13)),(e(),i(s,null,{default:r(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLI%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20G%5B%22%E5%AE%88%E5%8D%AB%22%5D%0A%20%20G%20--%3E%20M%5B%22%E4%B8%AD%E9%97%B4%22%5D%0A%20%20M%20--%3E%20E%5B%22%E5%87%BA%E5%8F%A3%22%5D%0A%20%20E%20--%3E%20DST%5B%22%E7%9B%AE%E7%9A%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"路由隐私的根基是信息局部性：守卫知道客户端但不知目的，中间节点两者皆不全，出口知道目的但不知客户端。要把两端连起来，攻击者需同时控制或观察路径的两端——时序关联正是这么做的：在入口与出口同时记录时间标记再对齐。低延迟设计不做批量缓冲打乱，这是 Tor 承认的代价，全局被动观察者因此仍是理论强敌。经济学下一课解释为何已知漏洞长期留在生态里。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：你 10:00:00.1 发出请求，网站 10:00:00.4 收到；下一条间隔 3.2 秒发出，对侧也恰差 3.2 秒收到。把几十条这样的间隔序列对上，入口与出口两份日志就「咬合」了——这就是时序关联的全部原理。")],-1)),(e(),i(s,null,{default:r(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E5%85%A5%E5%8F%A3%E4%BE%A7%E8%A7%82%E5%AF%9F%E8%80%85%3Cbr%2F%3E%E8%AE%B0%E5%BD%95%EF%BC%9A%E5%AE%A2%E6%88%B7%E7%AB%AF%20IP%20%E4%B8%8E%E5%8F%91%E9%80%81%E6%97%B6%E9%97%B4%22%5D%20--%3E%20ALIGN%5B%22%E6%97%B6%E9%97%B4%E5%AF%B9%E9%BD%90%22%5D%0A%20%20OUT%5B%22%E5%87%BA%E5%8F%A3%E4%BE%A7%E8%A7%82%E5%AF%9F%E8%80%85%3Cbr%2F%3E%E8%AE%B0%E5%BD%95%EF%BC%9A%E7%9B%AE%E7%9A%84%E5%9C%B0%E5%9D%80%E4%B8%8E%E5%88%B0%E8%BE%BE%E6%97%B6%E9%97%B4%22%5D%20--%3E%20ALIGN%0A%20%20ALIGN%20--%3E%20MATCH%5B%22%E5%8C%B9%E9%85%8D%E9%97%B4%E9%9A%94%E5%BA%8F%E5%88%97%3Cbr%2F%3E%E6%89%BE%E4%B8%A4%E4%BB%BD%E6%97%A5%E5%BF%97%E7%9A%84%E5%85%AC%E5%85%B1%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20MATCH%20--%3E%20CORR%5B%22%E6%8E%A8%E6%96%AD%E8%AF%A5%E5%AE%A2%E6%88%B7%E7%AB%AF%E4%B8%8E%E8%AF%A5%E7%9B%AE%E7%9A%84%3Cbr%2F%3E%E5%B1%9E%E4%BA%8E%E5%90%8C%E4%B8%80%E6%9D%A1%E7%94%B5%E8%B7%AF%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写去匿名化的操作步骤；边界要点名：出口是明文汇聚点，恶意出口可做内容区分；不用网桥时目录公开列出全部节点，封锁者据此拉黑。安全经济学下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIR 藏查询；Tor 藏路径与 IP。</li><li>分层加密；出口模型要写清。</li><li>全局观察者仍强。</li><li>下一课安全经济学。</li><li>出处：Dingledine, Mathewson and Syverson, 2004。</li></ul>',4))])}const _=A(p,[["render",T]]);export{F as __pageData,_ as default};
